import * as React from "react";

/**
 * Double-tapping the nav item for the page you are already on takes you back to
 * the start of that page, in two steps. The first shows you where you are: the
 * scroll region returns to the top and every tab strip on the page brings its
 * active tab back into view, together. The second, once nothing needed
 * showing, goes to whatever the page registered as its start.
 *
 * The step is chosen from what is currently out of place rather than from a
 * second gesture inside a time window, so the sequence is self-correcting: a
 * double-tap with anything scrolled away always restores it, and one with
 * everything in view always resets.
 */

/** Milliseconds within which a second activation counts as a double. */
export const NAV_DOUBLE_MS = 350;

/** Scroll offsets below this count as "at the top" (sub-pixel, momentum drift). */
const AT_TOP_EPSILON = 4;

/**
 * A page publishes its start here; the nav consumes it. The two share no
 * parent -- the nav is Layout chrome and the tabs belong to the page -- so the
 * slots are refs rather than state: they are read at click time and never need
 * to re-render the nav.
 *
 * `reveals` holds one step per tab strip: each brings its active tab into view
 * and reports whether it had to. `reset` is the page's start.
 */
interface NavResetSlots {
  reset: React.MutableRefObject<(() => void) | null>;
  reveals: React.MutableRefObject<Set<() => boolean>>;
}

const NavResetContext = React.createContext<NavResetSlots | null>(null);

export interface NavResetProviderProps {
  children: React.ReactNode;
}

/**
 * Installs the slots. `AppShell` renders this, so an app built on the shell has
 * it already. Without a provider `useRegisterNavReset` and
 * `useRegisterNavReveal` are inert and the nav stops after the scroll step,
 * which is what a page with no tabs wants anyway.
 */
export function NavResetProvider({ children }: NavResetProviderProps) {
  const reset = React.useRef<(() => void) | null>(null);
  const reveals = React.useRef(new Set<() => boolean>());
  const slots = React.useMemo<NavResetSlots>(() => ({ reset, reveals }), []);
  return React.createElement(NavResetContext.Provider, { value: slots }, children);
}

/**
 * Registers what "back to the start" means for the page that calls it -- for a
 * tabbed page, selecting the first tab.
 *
 * ```tsx
 * useRegisterNavReset(() => setActiveTab(tabItems[0].id));
 * ```
 *
 * Pass `null` while the page has nowhere to go back to (already on the first
 * tab, or no tabs at all) and the nav's second step does nothing. The callback
 * is read through a ref, so an inline arrow does not re-register on every
 * render and the nav always invokes the latest one.
 */
export function useRegisterNavReset(fn: (() => void) | null): void {
  const slots = React.useContext(NavResetContext);
  const latest = React.useRef(fn);
  latest.current = fn;

  React.useEffect(() => {
    if (!slots) return;
    const slot = slots.reset;
    // `has` is what the nav tests to decide whether a second step exists, so it
    // has to track the CURRENT value rather than the one at registration time.
    const call = () => latest.current?.();
    const entry = latest.current ? call : null;
    slot.current = entry;
    return () => {
      if (slot.current === entry) slot.current = null;
    };
  });
}

/**
 * Registers a tab strip's "bring the active tab into view" step. The callback
 * returns true when it scrolled and false when the active tab was already in
 * view (or the strip is hidden at this breakpoint), so the nav knows whether
 * the gesture has done its first step or should move on to the reset.
 *
 * `TabBar` and `SidebarTabs` register themselves; a custom strip calls this
 * with its own check. The callback is read through a ref, so an inline arrow
 * does not re-register on every render.
 */
export function useRegisterNavReveal(fn: () => boolean): void {
  const slots = React.useContext(NavResetContext);
  const latest = React.useRef(fn);
  latest.current = fn;

  React.useEffect(() => {
    if (!slots) return;
    const set = slots.reveals.current;
    const call = () => latest.current();
    set.add(call);
    return () => {
      set.delete(call);
    };
  }, [slots]);
}

/** The registered slots, or null. Consumed by the nav components. */
export function useNavReset(): NavResetSlots | null {
  return React.useContext(NavResetContext);
}

/**
 * Resolves the scroll region the same way `useScrollReset` does: an element
 * with overflow of its own is the scroller, otherwise the window is. A Layout
 * hands its `AppMain` ref to both and each figures out the scroll model.
 */
interface ScrollHandle {
  atTop: boolean;
  get: () => number;
  set: (top: number) => void;
  /** Where user input lands while the region scrolls -- a real wheel/touch/key
   * cancels the animation, the user's gesture wins. */
  events: EventTarget;
}

function scroller(el: HTMLElement | null): ScrollHandle {
  if (el && el.scrollHeight > el.clientHeight) {
    return {
      atTop: el.scrollTop <= AT_TOP_EPSILON,
      get: () => el.scrollTop,
      set: (top) => {
        el.scrollTop = top;
      },
      events: el,
    };
  }
  return {
    atTop: window.scrollY <= AT_TOP_EPSILON,
    get: () => window.scrollY,
    set: (top) => window.scrollTo(0, top),
    events: window,
  };
}

// The double-tap's scroll-to-top animates along a settle curve evaluated in
// JS -- scrollTop has no CSS transition to inherit from, so the values live
// here rather than in the tokens. The curve winds up from rest (ease-in),
// accelerates through the travel, and eases into the top: the arrival IS the
// stop, no rebound.
const SCROLL_MS = 300; // duration-300
const SETTLE = cubicBezier(0.45, 0, 0.2, 1);

/** Standard CSS cubic-bezier evaluation: solve the x polynomial for t
 * (Newton, bisection fallback), then read y. */
function cubicBezier(x1: number, y1: number, x2: number, y2: number): (x: number) => number {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 8; i++) {
      const err = sampleX(t) - x;
      if (Math.abs(err) < 1e-5) return sampleY(t);
      const d = (3 * ax * t + 2 * bx) * t + cx;
      if (Math.abs(d) < 1e-6) break;
      t -= err / d;
    }
    let lo = 0;
    let hi = 1;
    while (hi - lo > 1e-5) {
      t = (lo + hi) / 2;
      if (sampleX(t) < x) lo = t;
      else hi = t;
    }
    return sampleY(t);
  };
}

const CANCEL_EVENTS = ["wheel", "touchstart", "pointerdown", "keydown"] as const;
// One animation per region: a fresh double-tap restarts cleanly instead of
// two frame loops fighting over the same scrollTop.
const running = new WeakMap<EventTarget, () => void>();

function animateToTop(region: ScrollHandle): void {
  const start = region.get();
  if (start <= 0) return;
  if (
    typeof matchMedia !== "undefined" &&
    matchMedia("(prefers-reduced-motion: reduce)").matches
  ) {
    region.set(0);
    return;
  }

  running.get(region.events)?.();
  let raf = 0;
  let done = false;
  const cancel = () => {
    done = true;
    cancelAnimationFrame(raf);
    for (const type of CANCEL_EVENTS) region.events.removeEventListener(type, cancel);
    running.delete(region.events);
  };
  for (const type of CANCEL_EVENTS) region.events.addEventListener(type, cancel, { passive: true });
  running.set(region.events, cancel);

  let t0: number | null = null;
  const frame = (now: number) => {
    if (done) return;
    if (t0 === null) t0 = now;
    if (now - t0 >= SCROLL_MS) {
      region.set(0);
      cancel();
      return;
    }
    region.set(start * (1 - SETTLE((now - t0) / SCROLL_MS)));
    raf = requestAnimationFrame(frame);
  };
  raf = requestAnimationFrame(frame);
}

/**
 * Returns the handler a nav item fires on activation. It only acts on the
 * SECOND activation within `NAV_DOUBLE_MS`, and only for the item whose page is
 * already showing -- activating any other item is a navigation, which owns the
 * gesture.
 */
export function useNavDoubleActivate(
  scrollRef?: React.RefObject<HTMLElement | null>,
): (active: boolean) => void {
  const slots = useNavReset();
  const lastAt = React.useRef(0);

  return React.useCallback(
    (active: boolean) => {
      if (!active) {
        lastAt.current = 0;
        return;
      }
      const now = Date.now();
      if (now - lastAt.current > NAV_DOUBLE_MS) {
        lastAt.current = now;
        return;
      }
      // Consume the pair, so a third tap starts a new one rather than
      // triggering again off the second.
      lastAt.current = 0;

      // Everything out of place restores in one motion; the reset waits for a
      // double-tap with nothing left to show.
      let restored = false;
      const region = scroller(scrollRef?.current ?? null);
      if (!region.atTop) {
        animateToTop(region);
        restored = true;
      }
      for (const reveal of slots?.reveals.current ?? []) {
        if (reveal()) restored = true;
      }
      if (restored) return;
      slots?.reset.current?.();
    },
    [slots, scrollRef],
  );
}
